export const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
export const BECH32_CHECKSUM_CONSTANT = 1;
export const CHECKSUM_LENGTH = 6;
export const MAX_ADDRESS_LENGTH = 90;

import { BECH32_CHECKSUM_CONSTANT } from "./constants.mjs";

const GENERATORS = [
  0x3b6a57b2,
  0x26508e6d,
  0x1ea119fa,
  0x3d4233dd,
  0x2a1462b3,
];

export function polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >> index) & 1) !== 0) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum;
}

export function expandHrp(hrp) {
  const highParts = [];
  const lowParts = [];

  for (const character of hrp) {
    const codePoint = character.codePointAt(0);
    highParts.push(codePoint >> 5);
    lowParts.push(codePoint & 31);
  }

  return highParts.concat([0], lowParts);
}

export function verifyChecksum(hrp, data) {
  return polymod(expandHrp(hrp).concat(data)) === BECH32_CHECKSUM_CONSTANT;
}

import { CHARSET } from "./constants.mjs";

export function decodeCharsetValues(text) {
  const values = [];

  for (const character of text) {
    const value = CHARSET.indexOf(character);
    if (value === -1) {
      return null;
    }
    values.push(value);
  }

  return values;
}

export function convertBits(values, fromBits, toBits, shouldPad) {
  let accumulator = 0;
  let bitCount = 0;
  const converted = [];
  const maximumValue = (1 << toBits) - 1;
  const maximumAccumulator = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of values) {
    if (value < 0 || value >> fromBits !== 0) {
      return null;
    }

    accumulator = ((accumulator << fromBits) | value) & maximumAccumulator;
    bitCount += fromBits;

    while (bitCount >= toBits) {
      bitCount -= toBits;
      converted.push((accumulator >> bitCount) & maximumValue);
    }
  }

  if (shouldPad) {
    if (bitCount !== 0) {
      converted.push((accumulator << (toBits - bitCount)) & maximumValue);
    }
  } else if (
    bitCount >= fromBits ||
    ((accumulator << (toBits - bitCount)) & maximumValue) !== 0
  ) {
    return null;
  }

  return converted;
}

export function formatPythonList(values) {
  return `[${values.join(", ")}]`;
}

export function formatDecodeResult(result) {
  if (result === null) {
    return "(None, None)";
  }

  const [version, program] = result;
  return `(${version}, ${formatPythonList(program)})`;
}

const OPTIONS = ["--a", "--b", "--help"];

function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function helpText(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function errorResult(programName, message) {
  return {
    type: "error",
    text: `${usageLine(programName)}\n${programName}: error: ${message}\n`,
  };
}

function resolveLongOption(optionText) {
  const matches = OPTIONS.filter((option) => option.startsWith(optionText));
  return matches.length === 1 ? matches[0] : null;
}

function looksLikeOption(value) {
  if (value === undefined || value === "-") {
    return false;
  }
  if (/^-\d/.test(value) || /^-\.\d/.test(value)) {
    return false;
  }
  return value.startsWith("-");
}

export function parseCliArguments(argv, programName) {
  const parsed = { a: undefined, b: undefined };
  const unrecognized = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--") {
      unrecognized.push(...argv.slice(index + 1));
      break;
    }

    if (token === "-h") {
      return { type: "help", text: helpText(programName) };
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const optionText = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const option = resolveLongOption(optionText);

      if (option === null) {
        unrecognized.push(token);
        continue;
      }

      if (option === "--help") {
        if (equalsIndex !== -1) {
          return errorResult(
            programName,
            `argument -h/--help: ignored explicit argument '${token.slice(equalsIndex + 1)}'`,
          );
        }
        return { type: "help", text: helpText(programName) };
      }

      if (equalsIndex !== -1) {
        parsed[option.slice(2)] = token.slice(equalsIndex + 1);
        continue;
      }

      const value = argv[index + 1];
      if (value === undefined || looksLikeOption(value)) {
        return errorResult(programName, `argument ${option}: expected one argument`);
      }

      parsed[option.slice(2)] = value;
      index += 1;
      continue;
    }

    unrecognized.push(token);
  }

  const missing = [];
  if (parsed.a === undefined) {
    missing.push("--a");
  }
  if (parsed.b === undefined) {
    missing.push("--b");
  }

  if (missing.length !== 0) {
    return errorResult(
      programName,
      `the following arguments are required: ${missing.join(", ")}`,
    );
  }

  if (unrecognized.length !== 0) {
    return errorResult(
      programName,
      `unrecognized arguments: ${unrecognized.join(" ")}`,
    );
  }

  return { type: "run", args: parsed };
}

import { CHECKSUM_LENGTH, MAX_ADDRESS_LENGTH } from "./constants.mjs";
import { verifyChecksum } from "./checksum.mjs";
import { decodeCharsetValues } from "./charsetValues.mjs";
import { convertBits } from "./bitConversion.mjs";

function hasPortableCharacterRange(address) {
  for (const character of address) {
    const codePoint = character.codePointAt(0);
    if (codePoint < 33 || codePoint > 126) {
      return false;
    }
  }
  return true;
}

export function decodeBech32Address(address) {
  if (!hasPortableCharacterRange(address)) {
    return null;
  }

  const allLowercase = address === address.toLowerCase();
  const allUppercase = address === address.toUpperCase();
  if (!allLowercase && !allUppercase) {
    return null;
  }

  const normalizedAddress = address.toLowerCase();
  const separatorIndex = normalizedAddress.lastIndexOf("1");

  if (
    separatorIndex < 1 ||
    separatorIndex + 7 > normalizedAddress.length ||
    normalizedAddress.length > MAX_ADDRESS_LENGTH
  ) {
    return null;
  }

  const hrp = normalizedAddress.slice(0, separatorIndex);
  const dataWithChecksum = decodeCharsetValues(
    normalizedAddress.slice(separatorIndex + 1),
  );

  if (dataWithChecksum === null || !verifyChecksum(hrp, dataWithChecksum)) {
    return null;
  }

  return {
    hrp,
    data: dataWithChecksum.slice(0, -CHECKSUM_LENGTH),
  };
}

export function decodeSegwitAddress(expectedHrp, address) {
  const decoded = decodeBech32Address(address);

  if (decoded === null || decoded.hrp !== expectedHrp) {
    return null;
  }

  const version = decoded.data[0];
  const program = convertBits(decoded.data.slice(1), 5, 8, false);

  if (program === null || program.length < 2 || program.length > 40) {
    return null;
  }

  if (version > 16) {
    return null;
  }

  if (version === 0 && program.length !== 20 && program.length !== 32) {
    return null;
  }

  return [version, program];
}

import { parseCliArguments } from "./lib/cliArguments.mjs";
import { decodeSegwitAddress } from "./lib/addressDecoder.mjs";
import { formatDecodeResult } from "./lib/pythonFormatting.mjs";

function programNameFromArgv(argv) {
  const scriptPath = argv[1] ?? "test5.mjs";
  const parts = scriptPath.split(/[\\/]/);
  return parts[parts.length - 1] || "test5.mjs";
}

function main() {
  const programName = programNameFromArgv(process.argv);
  const parsed = parseCliArguments(process.argv.slice(2), programName);

  if (parsed.type === "help") {
    process.stdout.write(parsed.text);
    return 0;
  }

  if (parsed.type === "error") {
    process.stderr.write(parsed.text);
    return 2;
  }

  const result = decodeSegwitAddress(parsed.args.a, parsed.args.b);
  process.stdout.write(`${formatDecodeResult(result)}\n`);
  return 0;
}

process.exitCode = main();

